document.querySelectorAll('.copy-code').forEach(button=>button.addEventListener('click',async()=>{const block=button.parentElement,code=block.querySelector('code'),status=block.querySelector('.copy-result');try{await navigator.clipboard.writeText(code.textContent);status.textContent='Copied complete import code.'}catch{const selection=window.getSelection(),range=document.createRange();range.selectNodeContents(code);selection.removeAllRanges();selection.addRange(range);status.textContent='Code selected. Press Ctrl+C or Command+C to copy.'}}));
